   616	{
   617	  bool notify_enabled;
   618	  struct bt_conn *notify_conn;
   619	  struct bt_conn *conn;
   620	  int ret;
   621	
   622	  pthread_mutex_lock(&g_lock);
   623	  if (attr_index == VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX)
   624	    {
   625	      notify_enabled = g_agent_event_notify_enabled;
   626	      notify_conn = g_agent_event_notify_conn;
   627	    }
   628	  else if (attr_index == VELAWEAR_BLE_AGENT_RESULT_ATTR_INDEX)
   629	    {
   630	      notify_enabled = g_agent_result_notify_enabled;
   631	      notify_conn = g_agent_result_notify_conn;
   632	    }
   633	  else if (attr_index == VELAWEAR_BLE_AGENT_MESSAGE_ATTR_INDEX)
   634	    {
   635	      notify_enabled = g_agent_message_notify_enabled;
   636	      notify_conn = g_agent_message_notify_conn;
   637	    }
   638	  else
   639	    {
   640	      pthread_mutex_unlock(&g_lock);
   641	      return VELAWEAR_ERR_INVAL;
   642	    }
   643	
