   176	static uint16_t velawear_agent_read_u16(const uint8_t *data)
   177	{
   178	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   179	}
   180	
   181	static uint32_t velawear_agent_read_u32(const uint8_t *data)
   182	{
   183	  return (uint32_t)data[0] |
   184	         ((uint32_t)data[1] << 8) |
   185	         ((uint32_t)data[2] << 16) |
   186	         ((uint32_t)data[3] << 24);
   187	}
