   214	      return -EINVAL;
   215	    }
   216	
   217	  start->stream_id = velawear_agent_read_u16(frame + 2);
   218	  start->sample_rate = velawear_agent_read_u16(frame + 4);
   219	  start->channels = frame[6];
   220	  start->bits_per_sample = frame[7];
   221	  start->sample_count = sample_count;
