   817	static int audio_music_hw_test(void)
   818	{
   819	  AUDCODEC_HandleTypeDef codec;
   820	  DMA_HandleTypeDef *dma = &g_audio_dma;
   821	  AUDCODEC_DACCfgTypeDef dac_cfg;
   822	  int ret = HAL_OK;
   823	  uint32_t phase = 0;
   824	  uint32_t total_samples = 0;
   825	  uint32_t total_ms = 0;
   826	  uint32_t wait_ms;
   827	  uint32_t waited = 0;
   828	  size_t note_index;
   829	
   830	  memset(&codec, 0, sizeof(codec));
   831	  memset(dma, 0, sizeof(*dma));
   832	  memset(&dac_cfg, 0, sizeof(dac_cfg));
   833	  codec.Instance = hwp_audcodec;
   834	  codec.Init.dac_cfg.opmode = 1;
   835	  codec.hdma[HAL_AUDCODEC_DAC_CH0] = dma;
   836	  /* The official SF32LB52 mapping uses request 41 for DAC0.  With the
   837	   * dynamic allocator the initial channel is only a hint; the HAL moves it
   838	   * to a free DMAC1 channel and the generic IRQ shims above dispatch it. */
   839	  dma->Instance = DMA1_Channel1;
   840	  dma->Init.Request = DMA_REQUEST_41;
   841	
   842	  syslog(LOG_INFO, "[AudioMusic] DMA melody begin\n");
   843	
   844	  /* Render the finite melody once.  The DAC DMA buffer is circular in the
   845	   * SiFli HAL, so the first transfer-complete callback is our end marker. */
   846	  for (note_index = 0;
   847	       note_index < sizeof(g_music_melody) / sizeof(g_music_melody[0]);
   848	       note_index++)
   849	    {
   850	      const audio_music_note_t *note = &g_music_melody[note_index];
   851	      uint32_t samples = (uint32_t)(((uint64_t)AUDIO_MUSIC_RATE *
   852	                                     note->duration_ms) / 1000);
   853	      uint64_t step = note->frequency_hz == 0 ? 0 :
   854	          (((uint64_t)note->frequency_hz << 32) / AUDIO_MUSIC_RATE);
   855	      uint32_t i;
   856	
   857	      total_ms += note->duration_ms;
   858	      for (i = 0; i < samples && total_samples < AUDIO_DMA_BUFFER_WORDS;
   859	           i++, total_samples++)
   860	        {
   861	          int16_t sample = note->frequency_hz == 0 ? 0 :
   862	            g_tone[(phase >> 27) & 31];
   863	          g_audio_dma_buffer[total_samples] = (uint32_t)(uint16_t)sample;
   864	          phase += (uint32_t)step;
   865	        }
   866	    }
   867	
   868	  if (total_samples == 0 || total_samples >= AUDIO_DMA_BUFFER_WORDS)
   869	    {
   870	      syslog(LOG_ERR, "[AudioMusic] DMA buffer sizing failed (%lu)\n",
   871	             (unsigned long)total_samples);
   872	      return -1;
   873	    }
   874	
   875	  audio_pa_set(false);
