   543	
   544	static void *velawear_watchdog_thread(void *context)
   545	{
   546	  velawear_agent_t *agent = (velawear_agent_t *)context;
   547	  bool reported_stall = false;
   548	
   549	  syslog(LOG_INFO, "[Watchdog] Software monitor started\n");
   550	  while (agent->running)
   551	    {
   552	      uint32_t age = velawear_now_ms() - agent->watchdog_last_main_ms;
   553	
   554	      if (age > 5000 && !reported_stall)
   555	        {
   556	          syslog(LOG_ERR,
   557	                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\n",
   558	                 (unsigned long)age);
   559	          reported_stall = true;
   560	        }
   561	      else if (age <= 5000)
   562	        {
   563	          reported_stall = false;
   564	        }
   565	
   566	      usleep(1000000);
   567	    }
   568	
   569	  syslog(LOG_INFO, "[Watchdog] Software monitor stopped\n");
   570	  return NULL;
   571	}
   572	
   573	static int velawear_watchdog_start_software(velawear_agent_t *agent)
   574	{
   575	  int ret;
   576	
   577	  agent->watchdog_last_main_ms = velawear_now_ms();
   578	  ret = pthread_create(&agent->watchdog_thread, NULL,
   579	                       velawear_watchdog_thread, agent);
   580	  if (ret != 0)
   581	    {
   582	      syslog(LOG_WARNING, "[Watchdog] Software monitor start failed: %d\n",
   583	             ret);
   584	      return ret;
   585	    }
   586	
   587	  agent->watchdog_thread_started = true;
   588	  return VELAWEAR_OK;
   589	}
   590	
   591	static int velawear_watchdog_start(velawear_agent_t *agent)
   592	{
   593	  int timeout_ms = 5000;
   594	  int ret;
   595	
   596	  if (agent == NULL)
   597	    {
   598	      return VELAWEAR_ERR_INVAL;
   599	    }
   600	
   601	  agent->watchdog_fd = open("/dev/watchdog0", O_RDWR);
   602	  if (agent->watchdog_fd < 0)
   603	    {
   604	      syslog(LOG_WARNING, "[Watchdog] /dev/watchdog0 unavailable: %d\n",
   605	             errno);
   606	      ret = velawear_watchdog_start_software(agent);
   607	      if (ret == VELAWEAR_OK)
   608	        {
   609	          syslog(LOG_INFO, "[Watchdog] Software-only monitor enabled\n");
   610	        }
   611	      return VELAWEAR_OK;
   612	    }
   613	
   614	  if (ioctl(agent->watchdog_fd, WDIOC_SETTIMEOUT, timeout_ms) < 0 ||
   615	      ioctl(agent->watchdog_fd, WDIOC_START, 0) < 0)
   616	    {
   617	      syslog(LOG_WARNING, "[Watchdog] Hardware watchdog start failed: %d\n",
   618	             errno);
   619	      close(agent->watchdog_fd);
   620	      agent->watchdog_fd = -1;
   621	      ret = velawear_watchdog_start_software(agent);
   622	      if (ret == VELAWEAR_OK)
   623	        {
   624	          syslog(LOG_INFO, "[Watchdog] Software-only monitor enabled\n");
   625	        }
   626	      return VELAWEAR_OK;
   627	    }
   628	
   629	  agent->watchdog_active = true;
   630	  ret = velawear_watchdog_start_software(agent);
   631	  if (ret != VELAWEAR_OK)
   632	    {
   633	      ioctl(agent->watchdog_fd, WDIOC_STOP, 0);
   634	      close(agent->watchdog_fd);
   635	      agent->watchdog_fd = -1;
   636	      agent->watchdog_active = false;
   637	      return VELAWEAR_OK;
   638	    }
   639	
   640	  syslog(LOG_INFO, "[Watchdog] Hardware watchdog started (%d ms)\n",
   641	         timeout_ms);
   642	  return VELAWEAR_OK;
   643	}
   644	
   645	static void velawear_watchdog_stop(velawear_agent_t *agent)
   646	{
   647	  if (agent == NULL)
   648	    {
   649	      return;
   650	    }
   651	
   652	  if (agent->watchdog_thread_started)
   653	    {
   654	      pthread_join(agent->watchdog_thread, NULL);
   655	      agent->watchdog_thread_started = false;
   656	    }
   657	
   658	  if (agent->watchdog_active && agent->watchdog_fd >= 0)
   659	    {
   660	      ioctl(agent->watchdog_fd, WDIOC_STOP, 0);
   661	      close(agent->watchdog_fd);
   662	    }
   663	
   664	  agent->watchdog_fd = -1;
   665	  agent->watchdog_active = false;
   666	}
   667	
   668	static void *velawear_imu_thread(void *context)
   669	{
   670	  velawear_agent_t *agent = (velawear_agent_t *)context;
   671	  bool fall_reported = false;
   672	  int last_motion_type = -1;
   673	
   674	  while (agent->running)
   675	    {
   676	      imu_data_t sample;
   677	      motion_state_t motion;
   678	      velawear_event_t event;
   679	      int period_us = 20000;
   680	
   681	      if (imu_sensor_read(&agent->imu, &sample) == VELAWEAR_OK)
   682	        {
   683	          int motion_type;
   684	
   685	          motion = imu_sensor_get_motion_state(&agent->imu);
   686	          motion_type = motion.is_running ? 2 :
   687	                        (motion.is_moving ? 1 : 0);
   688	
   689	          memset(&event, 0, sizeof(event));
   690	          event.type = VELAWEAR_EVENT_MOTION;
   691	          event.priority = VELAWEAR_PRIORITY_NORMAL;
   692	          event.timestamp = sample.timestamp;
   693	          event.data.motion.motion_type = motion_type;
   694	          event.data.motion.intensity = motion.motion_intensity;
   695	
   696	          if (motion_type != last_motion_type)
   697	            {
   698	              const char *motion_name = motion_type == 2 ? "跑步" :
   699	                                        (motion_type == 1 ? "活动" : "静止");
   700	              syslog(LOG_INFO, "[MVP] IMU state=%s intensity=%.2f\n",
   701	                     motion_name, motion.motion_intensity);
   702	              velawear_ble_update_motion(motion_type,
   703	                                         motion.motion_intensity);
   704	              /* 活动恢复时清除 BLE 告警状态。 */
   705	              if (last_motion_type == 0 && motion_type != 0)
   706	                {
   707	                  velawear_ble_set_alert(false);
   708	                }
   709	              last_motion_type = motion_type;
   710	
   711	              /* Motion state is edge-triggered for the event queue.  The IMU
   712	               * still samples at its configured rate for fall detection, but
   713	               * repeated identical states must not consume all MQ objects. */
   714	              if (event_manager_push(&agent->events, &event) < 0)
   715	                {
   716	                  syslog(LOG_WARNING,
   717	                         "[VelaWear] Failed to queue motion event\n");
   718	                }
   719	            }
   720	
   721	          if (motion.fall_detected && !fall_reported)
   722	            {
   723	              event.type = VELAWEAR_EVENT_FALL;
   724	              event.priority = VELAWEAR_PRIORITY_CRITICAL;
   725	              if (event_manager_push(&agent->events, &event) < 0)
   726	                {
   727	                  syslog(LOG_WARNING,
   728	                         "[VelaWear] Failed to queue fall event\n");
   729	                }
   730	              fall_reported = true;
   731	            }
   732	          else if (!motion.fall_detected)
   733	            {
   734	              fall_reported = false;
   735	            }
   736	        }
   737	
   738	      if (agent->config.imu_sample_rate_hz > 0)
   739	        {
   740	          period_us = 1000000 / agent->config.imu_sample_rate_hz;
   741	          if (period_us < 1000)
   742	            {
   743	              period_us = 1000;
   744	            }
   745	        }
   746	
   747	      usleep(period_us);
   748	    }
   749	
   750	  return NULL;
   751	}
