     1	/*
     2	 * VelaWear Agent - Audio Sensor Driver
     3	 *
     4	 * The Huangshan Pi has an onboard MEMS microphone wired to the SF32LB52
     5	 * AUDCODEC ADC.  The board port has no /dev/audio/pcm_in0 node, so this
     6	 * driver owns the direct AUDCODEC circular-DMA stream.
     7	 */
     8	
     9	#include <nuttx/config.h>
    10	#include <string.h>
    11	#include <unistd.h>
    12	#include <syslog.h>
    13	#include <time.h>
    14	
    15	#include "velawear.h"
    16	#include "../audio_hw_test.h"
    17	
    18	#define AUDIO_LEVEL_START_THRESHOLD 500U
    19	#define AUDIO_LEVEL_STOP_THRESHOLD  300U
    20	#define AUDIO_LEVEL_DEBOUNCE_HALVES 3U
    21	#define AUDIO_STREAM_START_GRACE_MS 500U
    22	
    23	static uint32_t audio_sensor_now_ms(void)
    24	{
    25	  struct timespec ts;
    26	
    27	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    28	    {
    29	      return (uint32_t)time(NULL) * 1000U;
    30	    }
    31	
    32	  return (uint32_t)(ts.tv_sec * 1000U + ts.tv_nsec / 1000000U);
    33	}
    34	
    35	static void audio_sensor_push_event(velawear_audio_t *audio,
    36	                                    bool active,
    37	                                    uint32_t avg_abs,
    38	                                    uint32_t peak_abs)
    39	{
    40	  velawear_events_t *events;
    41	  velawear_event_t event;
    42	
    43	  if (audio == NULL || audio->events == NULL)
    44	    {
    45	      return;
    46	    }
    47	
    48	  events = (velawear_events_t *)audio->events;
    49	  memset(&event, 0, sizeof(event));
    50	  event.type = VELAWEAR_EVENT_AUDIO;
    51	  event.priority = VELAWEAR_PRIORITY_NORMAL;
    52	  event.timestamp = audio_sensor_now_ms();
    53	  event.data.audio.active = active;
    54	  event.data.audio.avg_abs = avg_abs;
    55	  event.data.audio.peak_abs = peak_abs;
    56	  if (active)
    57	    {
    58	      strncpy(event.data.audio.text, "sound_start",
    59	              sizeof(event.data.audio.text) - 1);
    60	    }
    61	  else
    62	    {
    63	      strncpy(event.data.audio.text, "sound_end",
    64	              sizeof(event.data.audio.text) - 1);
    65	    }
    66	  event.data.audio.length = (int)strlen(event.data.audio.text);
    67	
    68	  if (event_manager_push(events, &event) < 0)
    69	    {
    70	      syslog(LOG_WARNING, "[AudioStream] audio event queue full\n");
    71	    }
    72	}
    73	
    74	static void *audio_sensor_thread(void *context)
    75	{
    76	  velawear_audio_t *audio = (velawear_audio_t *)context;
    77	  uint32_t start_ms = audio_sensor_now_ms();
    78	  uint32_t last_report_ms = start_ms;
    79	  uint32_t active_streak = 0;
    80	  uint32_t silent_streak = 0;
    81	  bool stream_has_samples = false;
    82	
    83	  syslog(LOG_INFO, "[AudioStream] level worker started\n");
    84	  while (audio->stream_running)
    85	    {
    86	      uint32_t avg_abs;
    87	      uint32_t peak_abs;
    88	      int ret = velawear_mic_stream_read_level(&avg_abs, &peak_abs);
    89	
    90	      if (ret < 0)
    91	        {
    92	          syslog(LOG_ERR, "[AudioStream] level read failed\n");
    93	          break;
    94	        }
    95	
    96	      if (ret > 0)
    97	        {
    98	          uint32_t now_ms = audio_sensor_now_ms();
    99	          bool previous_active;
   100	          bool current_active;
   101	
   102	          /* DMA is restarted after playback.  Do not interpret its first
   103	           * samples as microphone activity: DAC residue reaches the ADC
   104	           * briefly even when the external PA is disabled. */
   105	          if (!stream_has_samples)
   106	            {
   107	              stream_has_samples = true;
   108	              start_ms = now_ms;
   109	              active_streak = 0;
   110	              silent_streak = 0;
   111	              audio->level_active = false;
   112	            }
   113	
   114	          previous_active = audio->level_active;
   115	          current_active = previous_active;
   116	
   117	          if (!previous_active)
   118	            {
   119	              silent_streak = 0;
   120	              if (avg_abs >= AUDIO_LEVEL_START_THRESHOLD)
   121	                {
   122	                  active_streak++;
   123	                }
   124	              else
   125	                {
   126	                  active_streak = 0;
   127	                }
   128	
   129	              if (now_ms - start_ms >= AUDIO_STREAM_START_GRACE_MS &&
   130	                  active_streak >= AUDIO_LEVEL_DEBOUNCE_HALVES)
   131	                {
   132	                  current_active = true;
   133	                  active_streak = 0;
   134	                }
   135	            }
   136	          else
   137	            {
   138	              active_streak = 0;
   139	              if (avg_abs <= AUDIO_LEVEL_STOP_THRESHOLD)
   140	                {
   141	                  silent_streak++;
   142	                }
   143	              else
   144	                {
   145	                  silent_streak = 0;
   146	                }
   147	
   148	              if (silent_streak >= AUDIO_LEVEL_DEBOUNCE_HALVES)
   149	                {
   150	                  current_active = false;
   151	                  silent_streak = 0;
   152	                }
   153	            }
   154	
   155	          audio->latest_avg_abs = avg_abs;
   156	          audio->latest_peak_abs = peak_abs;
   157	          audio->level_active = current_active;
   158	
   159	          if (current_active != previous_active)
   160	            {
   161	              syslog(LOG_INFO,
   162	                     "[AudioStream] sound %s avg_abs=%lu peak_abs=%lu\n",
   163	                     current_active ? "start" : "end",
   164	                     (unsigned long)avg_abs, (unsigned long)peak_abs);
   165	              audio_sensor_push_event(audio, current_active, avg_abs,
   166	                                      peak_abs);
   167	              last_report_ms = now_ms;
   168	            }
   169	          else if (now_ms - last_report_ms >= 5000U)
   170	            {
   171	              syslog(LOG_INFO,
   172	                     "[AudioStream] level avg_abs=%lu peak_abs=%lu active=%d\n",
   173	                     (unsigned long)avg_abs, (unsigned long)peak_abs,
   174	                     current_active ? 1 : 0);
   175	              last_report_ms = now_ms;
   176	            }
   177	        }
   178	      else
   179	        {
   180	          /* Playback owns the codec.  The next ready half starts a fresh
   181	           * debounce window after microphone DMA is resumed. */
   182	          stream_has_samples = false;
   183	          active_streak = 0;
   184	          silent_streak = 0;
   185	        }
   186	
   187	      usleep(10000);
   188	    }
   189	
   190	  audio->stream_running = false;
   191	  syslog(LOG_INFO, "[AudioStream] level worker stopped\n");
   192	  return NULL;
   193	}
