---QUERY 1---
     1	/*
     2	 * VelaWear Agent - Action Manager Implementation
     3	 *
     4	 * Manages all actions: display, vibrate, BLE, LLM, etc.
     5	 *
     6	 * Author: pjjuihj
     7	 * Team: 329 - dela
     8	 */
     9	
    10	#include <nuttx/config.h>
    11	#include <stdio.h>
    12	#include <stdlib.h>
    13	#include <string.h>
    14	#include <errno.h>
    15	#include <syslog.h>
    16	#include <pthread.h>
    17	#include <unistd.h>
    18	
