    64	int event_manager_dispatch(velawear_events_t *events,
    65	                           velawear_event_t *event)
    66	{
    67	  event_handler_entry_t handlers[EVENT_HANDLER_MAX];
    68	  int handler_count;
    69	
    70	  if (events == NULL || event == NULL)
    71	    {
    72	      return VELAWEAR_ERR_INVAL;
    73	    }
    74	
    75	  /* Snapshot registrations before invoking callbacks.  Handlers are
    76	   * external code and may register another handler; never hold the manager
    77	   * lock across that call. */
    78	  pthread_mutex_lock(&events->lock);
    79	  handler_count = events->handler_count;
    80	  memcpy(handlers, events->handlers,
    81	         handler_count * sizeof(event_handler_entry_t));
    82	  pthread_mutex_unlock(&events->lock);
    83	
    84	  for (int i = 0; i < handler_count; i++)
    85	    {
    86	      int ret;
    87	
    88	      if (handlers[i].event_type == event->type ||
    89	          handlers[i].event_type == VELAWEAR_EVENT_NONE)
    90	        {
    91	          ret = handlers[i].handler(event, handlers[i].context);
    92	          if (ret < 0)
    93	            {
    94	              syslog(LOG_WARNING,
    95	                     "[EventMgr] Handler %d returned error: %d\n",
    96	                     i, ret);
    97	            }
    98	        }
    99	    }
   100	
   101	  return VELAWEAR_OK;
   102	}
