   105	int event_manager_init(velawear_events_t *events, int queue_size)
   106	{
   107	  struct mq_attr attr;
   108	  int ret;
   109	
   110	  if (events == NULL || queue_size < 1 || queue_size > EVENT_QUEUE_SIZE_MAX)
   111	    {
   112	      return VELAWEAR_ERR_INVAL;
   113	    }
   114	
   115	  memset(events, 0, sizeof(velawear_events_t));
   116	  events->queue_open = false;
   117	  events->queue_size = queue_size;
   118	
   119	  /* Initialize mutex */
   120	
   121	  ret = pthread_mutex_init(&events->lock, NULL);
   122	  if (ret != 0)
   123	    {
   124	      return VELAWEAR_ERR_IO;
   125	    }
   126	
   127	  ret = pthread_mutex_init(&events->pool_lock, NULL);
   128	  if (ret != 0)
   129	    {
   130	      pthread_mutex_destroy(&events->lock);
   131	      return VELAWEAR_ERR_IO;
   132	    }
   133	
   134	  /* Create message queue */
   135	
   136	  attr.mq_flags = 0;
   137	  attr.mq_maxmsg = queue_size;
   138	  /* Keep the mqueue payload within CONFIG_MQ_MAXMSGSIZE.  Events are
   139	   * copied through heap-backed pointers so the full event union can
   140	   * remain available to handlers. */
   141	  attr.mq_msgsize = sizeof(uintptr_t);
   142	  attr.mq_curmsgs = 0;
   143	
   144	  /* A crashed instance may leave pointer messages behind.  Remove the
   145	   * old queue before creating a fresh one for this process. */
   146	  mq_unlink(EVENT_QUEUE_NAME);
   147	
   148	  ret = file_mq_open(&events->queue, EVENT_QUEUE_NAME,
   149	                     O_CREAT | O_RDWR, 0644, &attr);
   150	  if (ret < 0)
   151	    {
   152	      syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
   153	             -ret);
   154	      pthread_mutex_destroy(&events->pool_lock);
   155	      pthread_mutex_destroy(&events->lock);
   156	      return VELAWEAR_ERR_IO;
   157	    }
   158	
   159	  events->queue_open = true;
   160	  events->running = false;
   161	  events->handler_count = 0;
   162	
   163	  syslog(LOG_INFO, "[EventMgr] Initialized queue=%d\n", queue_size);
   164	  return VELAWEAR_OK;
   165	}
