   167	int event_manager_start(velawear_events_t *events)
   168	{
   169	  int ret;
   170	
   171	  if (events->running)
   172	    {
   173	      return VELAWEAR_ERR_BUSY;
   174	    }
   175	
   176	  events->running = true;
   177	
   178	  ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
   179	  if (ret != 0)
   180	    {
   181	      syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
   182	      events->running = false;
   183	      return VELAWEAR_ERR_IO;
   184	    }
