   190	void event_manager_cleanup(velawear_events_t *events)
   191	{
   192	  if (events == NULL)
   193	    {
   194	      return;
   195	    }
   196	
   197	  if (events->running)
   198	    {
   199	      events->running = false;
   200	      pthread_join(events->thread, NULL);
   201	    }
