   204	    {
   205	      file_mq_close(&events->queue);
   206	      mq_unlink(EVENT_QUEUE_NAME);
   207	      events->queue_open = false;
   208	    }
   209	
   210	  pthread_mutex_destroy(&events->pool_lock);
   211	  pthread_mutex_destroy(&events->lock);
   212	
   213	  syslog(LOG_INFO, "[EventMgr] Cleaned up\n");
