   216	int event_manager_push(velawear_events_t *events, velawear_event_t *event)
   217	{
   218	  uintptr_t message;
   219	  int slot = -1;
   220	  int ret;
   221	
   222	  if (events == NULL || !events->queue_open || event == NULL)
   223	    {
   224	      return VELAWEAR_ERR_IO;
   225	    }
   226	
   227	  pthread_mutex_lock(&events->pool_lock);
   228	  /* Keep one pool slot for an Agent command.  Sensor producers must not
   229	   * prevent a connected BLE client from acknowledging or changing state. */
   230	  for (int i = 0; i < EVENT_POOL_SIZE - 1; i++)
   231	    {
   232	      if (!events->pool_used[i])
   233	        {
   234	          slot = i;
   235	          events->pool_used[i] = true;
   236	          memcpy(&events->pool[i], event, sizeof(*event));
   237	          break;
   238	        }
   239	    }
   240	
   241	  if (slot < 0 && event->type == VELAWEAR_EVENT_BLE_MSG &&
   242	      !events->pool_used[EVENT_POOL_SIZE - 1])
   243	    {
   244	      slot = EVENT_POOL_SIZE - 1;
   245	      events->pool_used[slot] = true;
   246	      memcpy(&events->pool[slot], event, sizeof(*event));
   247	    }
   248	  pthread_mutex_unlock(&events->pool_lock);
   249	
   250	  if (slot < 0)
   251	    {
   252	      return VELAWEAR_ERR_NOMEM;
   253	    }
   254	
   255	  /* The queue carries a stable pool slot, not a heap pointer. */
   256	  message = (uintptr_t)(slot + 1);
   257	  ret = file_mq_send(&events->queue, (const char *)&message,
   258	                     sizeof(message), event->priority);
   259	  if (ret < 0)
   260	    {
   261	      pthread_mutex_lock(&events->pool_lock);
   262	      events->pool_used[slot] = false;
   263	      pthread_mutex_unlock(&events->pool_lock);
   264	      syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", -ret);
   265	      return VELAWEAR_ERR_IO;
   266	    }
   267	
   268	  return VELAWEAR_OK;
   269	}
   270	
   271	int event_manager_pop(velawear_events_t *events, velawear_event_t *event,
   272	                      int timeout_ms)
   273	{
   274	  struct timespec timeout;
   275	  uintptr_t message;
   276	  ssize_t nbytes;
   277	  int slot;
   278	
   279	  if (events == NULL || !events->queue_open || event == NULL)
   280	    {
   281	      return VELAWEAR_ERR_IO;
   282	    }
   283	
   284	  /* Calculate timeout */
   285	  clock_gettime(CLOCK_REALTIME, &timeout);
   286	  timeout.tv_sec += timeout_ms / 1000;
   287	  timeout.tv_nsec += (timeout_ms % 1000) * 1000000;
   288	  if (timeout.tv_nsec >= 1000000000)
   289	    {
   290	      timeout.tv_sec++;
   291	      timeout.tv_nsec -= 1000000000;
   292	    }
   293	
   294	  nbytes = file_mq_timedreceive(&events->queue, (char *)&message,
   295	                                sizeof(message), NULL, &timeout);
   296	  if (nbytes < 0)
   297	    {
   298	      if (nbytes == -ETIMEDOUT)
   299	        {
   300	          return VELAWEAR_ERR_TIMEOUT;
   301	        }
   302	
   303	      return VELAWEAR_ERR_IO;
   304	    }
   305	
   306	  if (nbytes != sizeof(message) || message == 0 ||
   307	      message > EVENT_POOL_SIZE)
   308	    {
   309	      return VELAWEAR_ERR_IO;
   310	    }
   311	
   312	  slot = (int)message - 1;
   313	  pthread_mutex_lock(&events->pool_lock);
   314	  if (!events->pool_used[slot])
   315	    {
   316	      pthread_mutex_unlock(&events->pool_lock);
   317	      return VELAWEAR_ERR_IO;
   318	    }
   319	
   320	  memcpy(event, &events->pool[slot], sizeof(*event));
   321	  events->pool_used[slot] = false;
   322	  pthread_mutex_unlock(&events->pool_lock);
   323	
   324	  return VELAWEAR_OK;
   325	}
   326	
   327	int event_manager_register_handler(velawear_events_t *events,
   328	                                   uint32_t event_type,
   329	                                   event_handler_t handler,
   330	                                   void *context,
   331	                                   int priority)
   332	{
   333	  pthread_mutex_lock(&events->lock);
   334	
   335	  if (events->handler_count >= EVENT_HANDLER_MAX)
   336	    {
   337	      pthread_mutex_unlock(&events->lock);
   338	      return VELAWEAR_ERR_NOMEM;
   339	    }
   340	
   341	  events->handlers[events->handler_count].event_type = event_type;
   342	  events->handlers[events->handler_count].handler = handler;
   343	  events->handlers[events->handler_count].context = context;
   344	  events->handlers[events->handler_count].priority = priority;
   345	  events->handler_count++;
   346	
   347	  pthread_mutex_unlock(&events->lock);
   348	
   349	  syslog(LOG_INFO, "[EventMgr] Registered handler for type %lu\n",
   350	         (unsigned long)event_type);
   351	  return VELAWEAR_OK;
   352	}

